"""Preserve EPI-08..14 source reading and unresolved interfaces; no rule adoption."""
from datetime import datetime, timezone
from zipfile import ZipFile
from xml.etree import ElementTree as E
import hashlib, json
from apply_di7_ap_as_01 import G,R,A,info,encoded

def main():
    target=A/'COSMOLOGY_EPILOGUE_RELIC_NULL_READING_01.json';assert not target.exists()
    inv=json.loads((A/'ORIGINAL_COSMOLOGY_EPILOGUE_RULE_INVENTORY_01.json').read_bytes())
    ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
    def paragraphs(p):
        with ZipFile(p) as z:
            return [''.join(t.text or '' for t in q.findall('.//w:t',ns)) for q in E.fromstring(z.read('word/document.xml')).findall('.//w:p',ns)]
    source=G/inv['source']['path'];assert info(source)==inv['source'];ps=paragraphs(source)
    units=inv['units'][7:14];checks=[]
    for u in units:
        for e in u['evidence']:
            actual=ps[e['paragraphIndexZeroBased']];assert actual==e['text'] and hashlib.sha256(actual.encode()).hexdigest()==e['textSha256']
            checks.append({'id':u['id'],'paragraphIndexZeroBased':e['paragraphIndexZeroBased'],'passed':True})
    scans=[]
    for name in ['books/player/Decennium_Descent_Player_Rulebook_v6.docx','books/player/Decennium_Descent_Core_Systems_Bible_v2_Known_Descent.docx']:
        p=G/name;hits=[{'paragraphIndexZeroBased':i,'text':t,'textSha256':hashlib.sha256(t.encode()).hexdigest()} for i,t in enumerate(paragraphs(p)) if 'attunement' in t.lower() or ('attune' in t.lower() and 'item' in t.lower())]
        scans.append({'source':info(p),'query':'attunement OR (attune AND item), case-insensitive full document paragraphs','hits':hits,'finding':'No general magic-item attunement procedure located by this targeted query; most hits concern class/element/form language. This is not proof of absence from all sources.'})
    issues=[
      {'id':'EPI-08','questions':['Define an actual attunement procedure and finite item profile; do not borrow a standard external-game three-item cap without source/new-design declaration.','Pendant motive-certainty protection needs a precisely testable information scope; do not turn it into blanket divination immunity or a truth oracle.','Cancellation requires real caster and target agreement; define bearer action/range, what counts as one ongoing spell effect, multi-target/area/control/ongoing damage and absent/dead caster. It is not a universal Counterspell or resurrection. Retain actual beneficial Long Rest and item identity.']},
      {'id':'EPI-09','questions':['Supply full mundane spear profile, ownership/acquisition and Paladin/Soldier attunement gate. Finesse plus Heavy needs actual equipment-property rules and anatomy/size handling, not an imported external assumption.','Hesitation must be an actual finite timing/cost, not unlimited waiting or an opportunity to rewind a hit. Specify class versus character level, floor rounding, hit/miss, once-per-turn/attack restrictions and critical multiplication.','Do not grant Soldier an RP/divine engine or imply planar authority from radiant damage.']},
      {'id':'EPI-10','questions':['Specify fear confession as character fiction, action/voice/touch and finite pending WIS-save benefit/expiry.','On the actual next save determine final outcome after legal rerolls, advantage cancellation and source immunity before shattering; one mirror cannot distribute endless independent benefits.','Reforming at Sentinel discretion needs a concrete finite scene/cost/time and no free refresh via repeated reconstruction; ownership/attunement remain distinct.']},
      {'id':'EPI-11','questions':['Define glove physical profile, actual finite Matrix dust provenance and fabrication access. Naming dust is not a recovered way to mine the Equation, a known identity, an approved trade recipe or free stock.','Air-writing needs duration, range/visibility/volume/language, alteration/erasure and duplication rules. Glyph readability must not force beliefs or reveal who is secretly an ally/cultist.','Define fictional current advocacy of a peaceful passionless solution in a bounded scene; literacy does not grant protected comprehension, loyalty detection, KT/PT immunity or universal translation.']},
      {'id':'EPI-12','questions':['Twelve original scene seeds require executable geography, finite actors/stat blocks, exits, hazards, checks and fallback solutions. No new Courage skill: bind an actual ability/skill for the ladder.','Preserve original Wax Library source and jointly adopted Floor68 Melted Annex/Floor50 fallback; a general seed does not relocate that library or reset its finite destroyed books.','Toys, Silence Wraith and Echo Doppelganger need complete finite encounter profiles. Copy/release cannot circumvent existing forbidden copies, class prerequisites, resource limits or source identity.','Twin Wind timelines and Shardpool plane swap must use bounded explicitly NEW scene procedures with real clocks/return/party logistics, not promote pending Time Loop or planar spells.','Omega Theatre operates on character fiction and existing session-zero participation boundaries; no compulsion for players to disclose personal facts. Historical duel influence is a staged reenactment unless real chronology changes are expressly separately authored.','After Infinite Yield language is frame-dependent; portable use needs an explicit NEW staging wrapper, not an adopted campaign epoch.']},
      {'id':'EPI-13','questions':['Define actual Null-field boundaries and hourly exposure accumulation, partial hours, exiting/reentering, repeated saves, Null Veil duration and immunity. Separate Null Veil from Corrupted, Dissonance, expedition/serum Strain and KT/PT.','Passive Insight set5 must specify ordering versus modifiers and suppression; no hidden omniscience about motives.','All damage nonlethal is broader than the current melee-only knockout. Specify actual packet/DoT/minion/environment attribution and full damage/Wound/InstantDeath processing. Do not silently let nonlethal override fatalities or, conversely, allow repeated fatal damage while promising harmlessness.','BonusAction CHA15 shrug: exact success one-round suppression, failed Incapacitated endpoint, reattempt access while Incapacitated, concentration ending and independent exposure during suppression.','Mask confession and Archon blessing cleansing must name exact operative EPI04/EPI06 procedures after their review; mask fear advantage alone does not imply Null immunity. Define purge vs continuing field exposure and one-dose bittersap treatment.']},
      {'id':'EPI-14','questions':['Four named flora need finite habitats, actual recognition/harvest tools/check/DC/yield/time, replenishment and spoilage; Nature recognition alone does not spawn usable inventory.','Two parts bittersap plus one part echo lily and Bastion flame water need game-unit quantities, boiling apparatus/time, dose yield, costs/quality/failure and administration. No real-world botanical identification or synthesis is needed.','A new scoped antidote procedure does not silently alter the687 reviewed recipe catalog or grant generic poison/corruption/KT/PT cleansing. Tranquil thorn and Black hush moss have no effect merely because named.','Tie access to actual bounded sites or deliberate campaign provision; a plane chosen at character creation does not create harvested stock or free travel.']}
    ]
    dependencies=[R/'docs/mechanics/CORE_RESOLUTION_PLAYTEST.md',R/'docs/mechanics/CONDITIONS_PLAYTEST.md',R/'docs/mechanics/BODY_EQUIPMENT_PLAYTEST.md',R/'docs/mechanics/EQUIPMENT_ITEM_PROCEDURES.md',R/'docs/mechanics/CRAFTING_HARVEST_PLAYTEST.md',R/'docs/playtest/SESSION_ZERO_PLAYTEST.md',R/'data/director/cosmology/chronology_research_route_reviewed_01.json',R/'data/director/cosmology/souls_research_reviewed_01.json',R/'data/director/cosmology/planes_reviewed_01.json']
    target.write_bytes(encoded({'recordedAtUtc':datetime.now(timezone.utc).isoformat(),'status':'source reading and interface preparation; not submitted, no new rules adopted','source':inv['source'],'sourceInventory':info(A/'ORIGINAL_COSMOLOGY_EPILOGUE_RULE_INVENTORY_01.json'),'units':units,'paragraphChecks':checks,'attunementSearch':scans,'interfaceQuestions':issues,'currentDependencyFiles':[info(p) for p in dependencies],'pendingCharacterConference':'COSMOLOGY-EPILOGUE-CHARACTER-01 is submitted in actual Part3; await its reviewed definitions before dependent Null mechanics.','sourceInformationDeleted':0,'newRulesAdopted':False,'runtimeTestsExecuted':0,'humanPlaytested':False,'wholeGameApproved':False}))
    print(json.dumps({'receipt':info(target),'sourceParagraphChecks':len(checks),'units':len(units),'newRulesAdopted':False}))

if __name__=='__main__':main()
